using System;

namespace Tf2DemoSalvage.Content.Assets;

/// <summary>
/// The material system's <c>error</c> texture, the base texture of the error material that <c>FindMaterial</c> answers for a
/// material it cannot load.
/// </summary>
/// <remarks>
/// **Read in disassembly of TF2's <c>materialsystem.dll</c>** (2026-11-10). The texture manager's init (<c>0x1800550e0</c>)
/// makes it procedural: <c>"error"</c>, 32 by 32, one frame, <c>IMAGE_FORMAT_BGRA8888</c>, flags <c>0x40100</c>
/// (<c>NOMIP | SINGLECOPY</c>, so bilinear and no mips), regenerated by a <c>CCheckerboardTexture</c> of check size 4 and
/// colours <c>0x80000000</c> and <c>0xffff00ff</c>. Its generator (<c>0x180056880</c>) writes the second colour where
/// <c>(checkSize &amp; (x ^ y ^ z)) == 0</c> and the first elsewhere. So the squares are four texels, eight across, magenta
/// at the corner, and the black ones carry alpha 128. The error material is <c>UnlitGeneric</c> with <c>$model 1</c>,
/// <c>$decalscale 0.05</c> and <c>$basetexture error</c> (<c>0x180012b00</c>, <c>"___error.vmt"</c>).
/// </remarks>
public static class ErrorTexture
{
    /// <summary>Its edge, in texels.</summary>
    public const int Size = 32;

    /// <summary><c>CCheckerboardTexture</c>'s check size: the bit of <c>x ^ y</c> that picks the colour.</summary>
    public const int CheckSize = 4;

    /// <summary>The texels, four bytes each, red first.</summary>
    /// <returns>32 × 32 RGBA.</returns>
    public static byte[] Rgba()
    {
        byte[] pixels = new byte[Size * Size * 4];

        for (int y = 0; y < Size; y++)
        {
            for (int x = 0; x < Size; x++)
            {
                bool magenta = (CheckSize & (x ^ y)) == 0;
                Span<byte> texel = pixels.AsSpan(((y * Size) + x) * 4, 4);

                texel[0] = magenta ? (byte)0xff : (byte)0;
                texel[1] = 0;
                texel[2] = magenta ? (byte)0xff : (byte)0;
                texel[3] = magenta ? (byte)0xff : (byte)0x80;
            }
        }

        return pixels;
    }

    /// <summary>
    /// Whether the texture says it has alpha (<c>ITexture::IsTranslucent</c>): yes. <c>InitProceduralTexture</c>
    /// (<c>0x18003a700</c>) ORs <c>TEXTUREFLAGS_EIGHTBITALPHA</c> into the flags of a format with two or more alpha bits,
    /// and BGRA8888 has eight; so a <c>$translucent</c> material over it blends its alpha-128 squares.
    /// </summary>
    public const bool HasAlpha = true;

    /// <summary>The image, for the GPU.</summary>
    /// <returns>One RGBA level.</returns>
    public static TextureImage Image() => TextureImage.Rgba(Rgba());
}
